window.createComponents=function(s){
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const labels={STR:'力量',CON:'体质',SIZ:'体型',DEX:'敏捷',APP:'外貌',POW:'意志',INT:'智力',EDU:'教育'};
const C={escape:esc,heading:(title,kicker)=>`<div class="sheet-heading"><span>${esc(kicker||'ADVENTURER RECORD')}</span><h2>${esc(title)}</h2></div>`,section:(title,sub,body,cls='')=>`<section class="sheet-section ${cls}"><header class="section-heading"><h3>${esc(title)}</h3><small>${esc(sub)}</small></header><div class="section-body">${body}</div></section>`,
identity:()=>`<div class="identity-fields"><label class="name-field">冒险者姓名<input data-field="name" value="${esc(s.name)}" maxlength="24" aria-label="冒险者姓名"></label><label>年龄<input type="number" data-field="age" min="15" max="99" value="${s.age}" aria-label="年龄"></label><label class="occupation-field">职业<select data-field="occupation" aria-label="职业">${['古物学者','私家侦探','旅行记者','民俗医生'].map(x=>`<option ${s.occupation===x?'selected':''}>${x}</option>`).join('')}</select></label></div>`,
portrait:(cls='')=>`<figure class="portrait ${cls}"><img src="assets/character.png" alt="身着墨绿斗篷、砖红围巾，携带地图与手杖的旅行学者" width="1024" height="1536"><figcaption>Wanderer, keeper of forgotten stories.</figcaption></figure>`,
stats:()=>`<div class="stats-grid">${Object.entries(s.stats).map(([k,v])=>`<label class="stat-cell"><span class="stat-label"><b>${k}</b><span>${labels[k]}</span></span><input class="stat-value" type="number" min="1" max="99" value="${v}" data-stat="${k}" aria-label="${labels[k]} ${k}"><span class="stat-dots" aria-hidden="true">${Array.from({length:10},(_,i)=>`<i class="${i<Math.round(v/10)?'filled':''}"></i>`).join('')}</span></label>`).join('')}</div><div class="stat-total"><span>属性点数 <b data-derived="total">${Object.values(s.stats).reduce((a,b)=>a+b,0)}</b> / 480</span><span data-derived="budget-note">已分配完成</span></div>`,
compactStats:()=>`<div class="compact-stats">${Object.entries(s.stats).map(([k,v])=>`<label>${k}<input type="number" data-stat="${k}" min="1" max="99" value="${v}" aria-label="${labels[k]} ${k}"></label>`).join('')}</div><div class="stat-total">属性合计 <b data-derived="total">${Object.values(s.stats).reduce((a,b)=>a+b,0)}</b> / 480 <span data-derived="budget-note"></span></div>`,
resources:()=>`<div class="resource-list">${[['hp','生命','HP'],['mp','魔法','MP'],['san','理智','SAN']].map(([k,n,en])=>`<div class="resource resource-${k}"><div class="resource-label"><b>${en}</b><span>${n}</span></div><div class="resource-track"><i style="width:${100*s.resources[k]/s.maxResources[k]}%" data-resource-fill="${k}"></i></div><button data-action="resource" data-resource="${k}" data-delta="-1" aria-label="减少${n}">−</button><span class="resource-value" data-resource-value="${k}">${s.resources[k]} / ${s.maxResources[k]}</span><button data-action="resource" data-resource="${k}" data-delta="1" aria-label="增加${n}">＋</button></div>`).join('')}</div>`,
skills:()=>`<div class="skills-controls"><input class="skill-search" type="search" placeholder="寻找一项技能…" aria-label="搜索技能"><button class="roll-small" data-action="roll">掷 D100 ↗</button></div><div class="skill-list">${s.skills.map((x,i)=>`<div class="skill-row" data-skill-name="${esc(x.name)}"><span>${esc(x.name)}<small>${x.type}</small></span><label class="skill-input"><input type="number" min="0" max="99" data-skill-index="${i}" value="${x.value}" aria-label="${esc(x.name)}技能值"><span>%</span></label><span class="skill-threshold" data-threshold="${i}">${Math.floor(x.value/2)} / ${Math.floor(x.value/5)}</span><button data-action="roll" data-skill="${esc(x.name)}" data-index="${i}" aria-label="进行${esc(x.name)}检定">◇</button></div>`).join('')}</div><p class="skill-empty" hidden>没有找到这项技能。</p><div class="skill-footnote">数值 / 困难 / 极难 <span>兴趣点 <b data-derived="interest">${s.stats.INT*2}</b> · 职业点 <b data-derived="occupation">${s.stats.EDU*4}</b></span></div>`,
story:()=>`<div class="story-fields"><label>为什么踏上旅途？<textarea rows="3" data-field="backstory" aria-label="入局缘由">${esc(s.backstory)}</textarea></label><label>重要之人<input data-field="significantPeople" value="${esc(s.significantPeople)}" aria-label="重要之人"></label></div>`,
inventory:()=>`<div class="inventory-list">${[{icon:'⌕',name:'黄铜罗盘',note:'总是指向故乡'},{icon:'▱',name:'旧地图',note:'留着陌生人的批注'},{icon:'♧',name:'银叶标本',note:'第一次远行的纪念'}].map((x,i)=>`<button class="gear-item ${s.gear.includes(i)?'equipped':''}" data-action="gear" data-gear="${i}" aria-pressed="${s.gear.includes(i)}"><span class="gear-icon">${x.icon}</span><b>${x.name}</b><small>${s.gear.includes(i)?'已装入行囊':x.note}</small></button>`).join('')}</div>`,
traits:()=>`<div class="trait-list">${['好奇心旺盛','过目不忘','夜路常客','相信直觉'].map(x=>`<button data-action="trait" data-trait="${x}" aria-pressed="${s.traits.includes(x)}" class="${s.traits.includes(x)?'selected':''}">${s.traits.includes(x)?'✓ ':''}${x}</button>`).join('')}</div>`};return C;};
